/**
 * Validate extracted admin wiring against backend OpenAPI spec.
 *
 * Reads:
 * - docs/admin/admin-wiring-map.json (generated by extract-admin-endpoints.js)
 * - backend/src/docs/openapi-spec.ts (comprehensive spec, includes /admin)
 *
 * Writes:
 * - docs/admin/admin-wiring-validation.json
 * - docs/admin/admin-wiring-validation.md
 *
 * Heuristics:
 * - Path matching is done by "shape" (e.g., `/x/{id}/y` matches `/x/{anything}/y`)
 * - Method matching is exact.
 * - Security mismatches are reported for mutation endpoints (POST/PUT/PATCH/DELETE)
 */

const fs = require('fs');
const path = require('path');

// Enable TS loading for backend openapi-spec.ts
require('ts-node').register({
  transpileOnly: true,
  compilerOptions: { module: 'commonjs' },
});

const ROOT_DIR = path.resolve(__dirname, '../..'); // v2-ecosystem/
const WIRING_MAP_PATH = path.join(ROOT_DIR, 'docs', 'admin', 'admin-wiring-map.json');
const OPENAPI_SPEC_PATH = path.join(ROOT_DIR, 'backend', 'src', 'docs', 'openapi-spec.ts');
const OUTPUT_JSON = path.join(ROOT_DIR, 'docs', 'admin', 'admin-wiring-validation.json');
const OUTPUT_MD = path.join(ROOT_DIR, 'docs', 'admin', 'admin-wiring-validation.md');

function loadWiringMap() {
  if (!fs.existsSync(WIRING_MAP_PATH)) throw new Error(`Missing wiring map: ${WIRING_MAP_PATH}`);
  const raw = fs.readFileSync(WIRING_MAP_PATH, 'utf8');
  return JSON.parse(raw);
}

function loadOpenApiSpec() {
  if (!fs.existsSync(OPENAPI_SPEC_PATH)) throw new Error(`Missing OpenAPI spec: ${OPENAPI_SPEC_PATH}`);
  // eslint-disable-next-line import/no-dynamic-require
  const mod = require(OPENAPI_SPEC_PATH);
  if (!mod || !mod.openApiFullSpec) throw new Error(`openApiFullSpec not exported from ${OPENAPI_SPEC_PATH}`);
  return mod.openApiFullSpec;
}

function shape(p) {
  return String(p).replace(/\{[^}]+\}/g, '{}');
}

function normalizeMethod(method) {
  return String(method).toLowerCase();
}

function isMutationMethod(methodUpper) {
  return ['POST', 'PUT', 'PATCH', 'DELETE'].includes(String(methodUpper).toUpperCase());
}

function main() {
  const wiring = loadWiringMap();
  const openApi = loadOpenApiSpec();

  const openApiPaths = Object.keys(openApi.paths || {});
  const openApiByShape = new Map(); // shape -> pathKeys[]
  for (const p of openApiPaths) {
    const s = shape(p);
    const existing = openApiByShape.get(s) || [];
    existing.push(p);
    openApiByShape.set(s, existing);
  }

  const pages = wiring.pages || [];

  const sectorStats = {};
  const issues = [];

  function ensureSector(sector) {
    if (!sectorStats[sector]) {
      sectorStats[sector] = {
        totalEndpoints: 0,
        missingPaths: 0,
        missingMethods: 0,
        securityMismatches: 0,
      };
    }
    return sectorStats[sector];
  }

  for (const page of pages) {
    const sector = page.sector || 'Unknown';
    const stat = ensureSector(sector);
    const endpoints = page.endpoints || [];
    stat.totalEndpoints += endpoints.length;

    for (const ep of endpoints) {
      const methodUpper = ep.method;
      const method = normalizeMethod(methodUpper);
      const openApiPath = ep.openApiPath;
      const openApiShape = shape(openApiPath);

      const candidates = openApiByShape.get(openApiShape) || [];

      if (candidates.length === 0) {
        stat.missingPaths += 1;
        issues.push({
          type: 'MISSING_PATH',
          sector,
          pageRoute: page.route,
          pageFile: page.file,
          endpoint: {
            method: methodUpper,
            frontendTemplatePath: ep.frontendTemplatePath,
            openApiPath,
          },
          details: `No OpenAPI path matches shape: ${openApiShape}`,
        });
        continue;
      }

      // Find a candidate path that supports the method.
      let matchedPathKey = null;
      let methodSpec = null;
      for (const candidatePathKey of candidates) {
        const pathItem = openApi.paths[candidatePathKey];
        if (pathItem && pathItem[method]) {
          matchedPathKey = candidatePathKey;
          methodSpec = pathItem[method];
          break;
        }
      }

      if (!matchedPathKey || !methodSpec) {
        stat.missingMethods += 1;
        issues.push({
          type: 'MISSING_METHOD',
          sector,
          pageRoute: page.route,
          pageFile: page.file,
          endpoint: {
            method: methodUpper,
            frontendTemplatePath: ep.frontendTemplatePath,
            openApiPath,
          },
          details: `OpenAPI has path(s) for shape ${openApiShape} but no ${methodUpper} operation.`,
          openApiCandidatePaths: candidates,
        });
        continue;
      }

      // Security check: only enforce for mutations, because GET endpoints may be public.
      if (isMutationMethod(methodUpper)) {
        const sec = methodSpec.security;
        const hasSecurity = Array.isArray(sec) ? sec.length > 0 : false;
        if (!hasSecurity) {
          stat.securityMismatches += 1;
          issues.push({
            type: 'SECURITY_MISMATCH',
            sector,
            pageRoute: page.route,
            pageFile: page.file,
            endpoint: {
              method: methodUpper,
              frontendTemplatePath: ep.frontendTemplatePath,
              openApiPath,
            },
            details: `OpenAPI operation exists at ${matchedPathKey} but has no security requirement.`,
            matchedOpenApiPath: matchedPathKey,
          });
        }
      }
    }
  }

  // Sort issues for readability: worse first.
  const issueRank = (t) => ({ MISSING_PATH: 1, MISSING_METHOD: 2, SECURITY_MISMATCH: 3 }[t] || 99);
  issues.sort((a, b) => issueRank(a.type) - issueRank(b.type) || a.sector.localeCompare(b.sector));

  const report = {
    generatedAt: new Date().toISOString(),
    wiringMap: {
      path: WIRING_MAP_PATH,
      inventoryCount: wiring.inventoryCount,
      pagesCount: pages.length,
    },
    validation: {
      openApiSpec: OPENAPI_SPEC_PATH,
      openApiPathsCount: openApiPaths.length,
      matching: {
        usesShapeNormalizationForPathParams: true,
        securityCheckMutationOnly: true,
      },
    },
    sectorStats,
    issues,
  };

  ensureDir(path.dirname(OUTPUT_JSON));
  fs.writeFileSync(OUTPUT_JSON, JSON.stringify(report, null, 2), 'utf8');

  // Markdown summary
  let md = `# Admin Wiring Validation\n\n`;
  md += `Generated: ${report.generatedAt}\n\n`;
  md += `## Sector Summary\n\n`;
  md += `| Sector | Total Endpoints | Missing Paths | Missing Methods | Security Mismatches |\n`;
  md += `|---|---:|---:|---:|---:|\n`;
  const sectorKeys = Object.keys(sectorStats).sort((a, b) => a.localeCompare(b));
  for (const sectorKey of sectorKeys) {
    const s = sectorStats[sectorKey];
    md += `| ${sectorKey} | ${s.totalEndpoints} | ${s.missingPaths} | ${s.missingMethods} | ${s.securityMismatches} |\n`;
  }

  md += `\n## Issues\n\n`;
  if (issues.length === 0) {
    md += `No issues found.\n`;
  } else {
    for (const issue of issues) {
      md += `### ${issue.type}\n\n`;
      md += `- Sector: \`${issue.sector}\`\n`;
      md += `- Page: \`${issue.pageRoute}\`\n`;
      md += `- Endpoint: \`${issue.endpoint.method} ${issue.endpoint.openApiPath}\`\n`;
      if (issue.details) md += `- Details: ${issue.details}\n`;
      if (issue.openApiCandidatePaths) md += `- Candidates: ${issue.openApiCandidatePaths.join(', ')}\n`;
      md += `\n`;
    }
  }

  fs.writeFileSync(OUTPUT_MD, md, 'utf8');
  console.log(`Admin wiring validation generated: ${OUTPUT_JSON}`);
  console.log(`- Issues: ${issues.length}`);
  console.log(`- Markdown: ${OUTPUT_MD}`);
}

function ensureDir(dirPath) {
  if (!fs.existsSync(dirPath)) fs.mkdirSync(dirPath, { recursive: true });
}

main();

